import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:path/path.dart' as p;

import '../../../services/app_paths.dart';
import '../models/toonflow_studio_config.dart';

/// 本工具生成的 override 文件名。
const String kToonflowOverrideFileName = 'docker-compose.override.yml';

/// 标记注释的首行。只有以它开头的文件才会被本工具重写；别的文件先备份
/// （spec: 运行时配置以 override 注入而不修改上游工程文件）。
const String kToonflowOverrideMarker =
    '# Generated by V8WorkToolbox Toonflow studio tool';

/// Override 文件的生成、读取与安全重写。
///
/// **为什么用 override 而不是改上游 `compose.yaml`**：spike 里直接改原文件
/// 验证过可行，但用户 `git pull` 一次就丢，且会让 Toonflow 仓库出现本地未
/// 提交改动，干扰后续升级。override 是 compose 原生的「本地部署差异」机制，
/// 对上游零侵入。
class ToonflowOverrideStore {
  ToonflowOverrideStore._();
  static final ToonflowOverrideStore instance = ToonflowOverrideStore._();

  /// 生成 override 内容。
  ///
  /// 三件事（spike 2026-10-11 结论）：
  /// 1. 端口映射到用户配置的宿主机端口；
  /// 2. **bind mount 替代命名卷**——资产桥要直接文件系统读写工作区与素材；
  /// 3. `user: "<uid>:<gid>"` 让容器内进程以宿主机当前用户身份运行。
  ///
  /// `!override` 标签必须带：compose 对 `ports` 与 `volumes` 的默认合并行为
  /// 都是**追加**，不带标签会导致 3000 同时绑两个端口、`/app/data` 同时挂
  /// 两个卷。
  ///
  /// **卷条目整条加引号**，不能只引宿主机路径段。compose v5 的 go-yaml 解析器
  /// 把 `- "<host>":/app/data` 判成「块集合里少了 '-'」而直接报错——引号在
  /// 值中间结束，剩下的 `:/app/data` 就落到了缩进错误的位置。整条引起来
  /// （`- "<host>:/app/data"`）既躲开这个解析问题，也仍然满足 YAML 对含空格
  /// 标量的引用要求（实测 compose v5.5.1 两种形态都能正确解析出 bind）。
  String render(ToonflowStudioConfig config, {required String uid, required String gid}) {
    final buffer = StringBuffer()
      ..writeln(kToonflowOverrideMarker)
      ..writeln('# 本文件由 V8WorkToolbox 的 Toonflow 漫剧工坊工具自动生成与维护。')
      ..writeln('# 手工修改会在下次启动时被覆盖；如需长期定制请改上游')
      ..writeln('# docker-compose.yaml，并把这个工具的端口/数据目录配置对齐。')
      ..writeln('# 详见 openspec/changes/add-toonflow-studio-toolbox/design.md 决策 2。')
      ..writeln('services:')
      ..writeln('  toonflow:')
      // 容器内进程以宿主机当前用户身份运行。Docker Desktop 的 VirtioFS 实际
      // 绕过 POSIX 权限（spike 实测不加也能写），但这让将来换到 Linux 原生
      // Docker 时写入依然成立。
      ..writeln('    user: "$uid:$gid"')
      ..writeln('    ports: !override')
      ..writeln('      - "127.0.0.1:${config.httpPort}:3000"')
      ..writeln('    volumes: !override')
      ..writeln('      - "${_escapeYaml(AppPaths.toonflowDataDir.path)}:/app/data"');

    return buffer.toString();
  }

  /// 把路径转成 YAML 双引号标量的**内部**形态。
  ///
  /// 只做转义、不加引号——调用方负责把整条卷字符串包进引号
  /// （`- "<host>:/app/data"`）。引号只包 host 一半会让 compose v5 的
  /// go-yaml 报「did not find expected '-' indicator」而拒绝加载整个文件。
  static String _escapeYaml(String path) =>
      path.replaceAll(r'\', r'\\').replaceAll('"', r'\"');

  /// override 文件路径。
  String pathFor(String projectDir) =>
      p.join(projectDir, kToonflowOverrideFileName);

  /// 读取现有内容；不存在返回 null。
  String? read(String projectDir) {
    final file = File(pathFor(projectDir));
    if (!file.existsSync()) return null;
    try {
      return file.readAsStringSync();
    } catch (e) {
      debugPrint('[ToonflowOverrideStore] 读取 override 失败: $e');
      return null;
    }
  }

  /// 该文件是否由本工具生成（可安全重写）。
  bool isManaged(String projectDir) {
    final content = read(projectDir);
    if (content == null) return false;
    return content.trimLeft().startsWith(kToonflowOverrideMarker);
  }

  /// 写入 override。
  ///
  /// 返回是否发生了备份（调用方需告知用户——非本工具生成的文件被替换是
  /// 意外情况，静默覆盖违反 spec 的承诺）。
  bool write(
    String projectDir,
    ToonflowStudioConfig config, {
    required String uid,
    required String gid,
  }) {
    final file = File(pathFor(projectDir));
    var backedUp = false;

    if (file.existsSync() && !isManaged(projectDir)) {
      final backup = File(
        p.join(
          AppPaths.toonflowDir.path,
          '$kToonflowOverrideFileName.bak-${DateTime.now().millisecondsSinceEpoch}',
        ),
      );
      try {
        AppPaths.toonflowDir.createSync(recursive: true);
        file.copySync(backup.path);
        backedUp = true;
        debugPrint('[ToonflowOverrideStore] 已备份非托管 override → ${backup.path}');
      } catch (e) {
        debugPrint('[ToonflowOverrideStore] 备份失败（仍继续写入）: $e');
      }
    }

    file.writeAsStringSync(render(config, uid: uid, gid: gid));
    return backedUp;
  }

  /// 删除 override（回滚用）。仅删除本工具生成的那份。
  bool remove(String projectDir) {
    final file = File(pathFor(projectDir));
    if (!file.existsSync()) return false;
    if (!isManaged(projectDir)) return false;
    try {
      file.deleteSync();
      return true;
    } on FileSystemException catch (e) {
      debugPrint('[ToonflowOverrideStore] 删除 override 失败: $e');
      return false;
    }
  }

  /// 测试用：解析 override 的关键字段，供断言。
  ///
  /// 不引入 YAML 解析库——只需要验证端口、卷与 user 三项，正则足够且不会
  /// 因为上游 compose 结构变化而崩。
  static Map<String, String> decodeOverride(String content) {
    final result = <String, String>{};
    final userMatch = RegExp(r'user:\s*"([^"]+)"').firstMatch(content);
    if (userMatch != null) result['user'] = userMatch.group(1)!;
    final portMatch = RegExp(r'127\.0\.0\.1:(\d+):3000').firstMatch(content);
    if (portMatch != null) result['hostPort'] = portMatch.group(1)!;
    // 取 `- "<host>:/app/data"` 里的 host 段。整条卷字符串被引号包住（含空格
    // 的宿主机路径必须加引号，compose v5 的 go-yaml 也不接受引号只包一半），
    // 取回时剥掉——否则调用方拿到的路径和真实目录对不上。
    //
    // 写成两种形态而不是一个宽松正则：带引号和不带引号的路径用同一个模式
    // 匹配时，`[^"\n]+` 会把结尾的引号一起吃进来，得到的路径以 `"` 结尾。
    final volMatch = RegExp(r'-\s+"([^"]+):/app/data"').firstMatch(content) ??
        RegExp(r'-\s+([^\s"\n]+):/app/data').firstMatch(content);
    if (volMatch != null) {
      result['bindMount'] = volMatch.group(1)!.trim();
    }
    return result;
  }
}
